test("breakit Net.Update: two players' reports made exactly 24 h apart still make a newer version trusted", function()
	local w = T.newWorld()
	local r = T.rider(w, T.TESTCHAR, { version = "2.3.0" })
	T.settle(w)
	local W = r.W
	local realNow = W.Now
	ok(W.HeardVersion("bob stone", "2.3.1"), "Bob's report counted")
	W.Now = function() return realNow() + 86400 end
