	eq(W.NewerVersion(), "2.3.1", "Bob's report is exactly 24 h old and still counts: 2.3.1 is trusted")
	eq(W.db.newer and W.db.newer.ver, "2.3.1", "the newer version is saved")
	T.clean(w)
end)

